// frontend/src/components/Sidebar.jsx
import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import ProfileMenu from "./ProfileMenu";

export default function Sidebar({ sessions = [], onLoadSession = () => {}, onNewChat = () => {} }) {
  const [remoteSessions, setRemoteSessions] = useState([]);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    fetch("/api/sessions/list")
      .then((r) => (r.ok ? r.json() : []))
      .then((data) => {
        if (Array.isArray(data)) setRemoteSessions(data);
      })
      .catch(() => setRemoteSessions([]));
  }, []);

  const mergedSessions = React.useMemo(() => {
    const map = new Map();
    (sessions || []).forEach((s) => {
      if (s && s.id) map.set(String(s.id), s);
    });
    (remoteSessions || []).forEach((rs) => {
      if (rs && rs.id && !map.has(String(rs.id))) map.set(String(rs.id), rs);
    });
    return Array.from(map.values()).slice(0, 20);
  }, [sessions, remoteSessions]);

  const navBtnStyle = {
    display: "block",
    width: "100%",
    padding: "8px 10px",
    borderRadius: 8,
    background: "#fff",
    border: "1px solid #e6eef8",
    textAlign: "left",
    cursor: "pointer",
  };

  function handleNewChat() {
    try {
      onNewChat();
    } catch (e) {
      // defensive
      console.error("onNewChat callback error:", e);
    }
    navigate("/");
  }

  function handleLoadSession(sess) {
    try {
      onLoadSession(sess);
    } catch (e) {
      console.error("onLoadSession callback error:", e);
    }
    navigate("/");
  }

  return (
    <aside className="nav" style={{ display: "flex", flexDirection: "column", height: "100%", padding: 14 }}>
      <div style={{ marginBottom: 18 }}>
        <button className="btn-new" style={{ width: "100%", padding: "10px 12px", borderRadius: 8, background: "#7c3aed", color: "#fff", border: "none", cursor: "pointer" }} onClick={handleNewChat}>
          + New Chat
        </button>

        <div style={{ fontWeight: 700, color: "#334155", margin: "12px 0 8px 0" }}>Chat History</div>

        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 12 }}>
          {mergedSessions.length === 0 ? (
            <div className="history-item" style={{ padding: "8px 10px", borderRadius: 8, background: "#fbfcff", color: "#475569" }}>
              No saved chats yet
            </div>
          ) : (
            mergedSessions.slice(0, 10).map((s) => (
              <div
                key={s.id}
                className="history-item"
                onClick={() => handleLoadSession(s)}
                style={{
                  cursor: "pointer",
                  padding: "8px 10px",
                  borderRadius: 8,
                  background: "#fff",
                  border: "1px solid #eef2ff",
                  color: "#0f172a",
                }}
                title={s.title || "Open chat"}
              >
                {s.title || `Trip ${new Date(s.createdAt || Date.now()).toLocaleString()}`}
              </div>
            ))
          )}
        </div>

        <div style={{ marginTop: 6 }}>
          <div style={{ fontWeight: 700, color: "#334155", marginBottom: 8 }}>Navigation</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <Link to="/flights" style={{ textDecoration: "none" }}>
              <button style={{ ...navBtnStyle, borderColor: location.pathname === "/flights" ? "#C4B5FD" : navBtnStyle.border }}>
                ✈️ Flight Search
              </button>
            </Link>

            <Link to="/hotels" style={{ textDecoration: "none" }}>
              <button style={{ ...navBtnStyle, borderColor: location.pathname === "/hotels" ? "#C4B5FD" : navBtnStyle.border }}>
                🏨 Hotels & Cuisines
              </button>
            </Link>

            <Link to="/news" style={{ textDecoration: "none" }}>
              <button style={{ ...navBtnStyle, borderColor: location.pathname === "/news" ? "#C4B5FD" : navBtnStyle.border }}>
                📰 Travel News & Blogs
              </button>
            </Link>
          </div>
        </div>
      </div>

      <div style={{ marginTop: "auto", paddingTop: 12 }}>
        <ProfileMenu />
      </div>
    </aside>
  );
}
